BEGIN
 FOR g IN SELECT * FROM jsonb_each(spec) LOOP
 SELECT jsonb_agg(jsonb_build_object('key',k,'shape','round','size','large','font','cairo','align','center','textScale','large','weight','strong','spacing','wide','spaceBlock','wide','outerGap','wide','border','strong','shadow','soft') ORDER BY ord) INTO rows FROM jsonb_array_elements_text(g.value->'keys') WITH ORDINALITY a(k,ord);
 patch:=jsonb_build_object(g.key,rows);
 IF NOT ff_private.a07_valid_elements(patch,g.value->>'screen') THEN RAISE EXCEPTION 'registry validation %',g.key;END IF;
 IF ff_private.a07_valid_elements(patch,CASE WHEN g.value->>'screen'='finance' THEN 'driver' ELSE 'finance' END) OR ff_private.a07_valid_elements(jsonb_build_object(g.key,jsonb_set(rows,'{0,key}','"unknown_unsafe"')),g.value->>'screen') OR ff_private.a07_valid_elements(jsonb_build_object(g.key,jsonb_set(rows,'{0,hidden}','true')),g.value->>'screen') THEN RAISE EXCEPTION 'scope/key/visibility violation %',g.key;END IF;
 invalid:=jsonb_build_object(g.key,jsonb_set(rows,'{0,align}','"end"'));
 IF ff_private.a09_merge_elements(g.value->>'screen',patch,patch,invalid,ARRAY['layout','buttons','colors']) IS NOT NULL THEN RAISE EXCEPTION 'delegation bypass %',g.key;END IF;
 tested:=tested+jsonb_array_length(rows);
 END LOOP;
 IF tested<>662 THEN RAISE EXCEPTION 'count mismatch %',tested;END IF;
END $qa$;
